#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry planar_area. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section HexagonArea. Variable R : realType. Variables A B C P Q R S T U : 'rV[R]_2. Hypothesis triangle_noncollinear : ~ colinear A B C. Hypothesis PA_eq_AB : dist P A = dist A B. Hypothesis AB_eq_BS : dist A B = dist B S. Hypothesis QA_eq_AC : dist Q A = dist A C. Hypothesis AC_eq_CT : dist A C = dist C T. Hypothesis RB_eq_BC : dist R B = dist B C. Hypothesis BC_eq_CU : dist B C = dist C U. Hypothesis P_A_B_collinear : colinear P A B. Hypothesis B_S_collinear : colinear A B S. Hypothesis Q_A_C_collinear : colinear Q A C. Hypothesis C_T_collinear : colinear A C T. Hypothesis R_B_C_collinear : colinear R B C. Hypothesis C_U_collinear : colinear B C U. Hypothesis A_between_P_B : between P A B. Hypothesis B_between_A_S : between A B S. Hypothesis A_between_Q_C : between A Q C. Theorem extended_hexagon_area : exists area : R, area > 0. Proof. Admitted. End
